import type { BlogPost } from "./blog-posts";

const team = { author: "TheSocialPundit Team", authorRole: "Editorial", isGuide: true } as const;
const PUBLISHED = "2026-10-15";

function readTime(post: Omit<BlogPost, "readTime">) {
  const words = [post.summary ?? "", ...post.content, ...(post.faqs ?? []).flatMap(faq => [faq.question, faq.answer])]
    .join(" ").split(/\s+/).length;
  return `${Math.max(3, Math.round(words / 220))} min read`;
}

